	  t_country(1123).idDepto := 6404;
	  t_country(1123).idMunicipio := 6895;
	  t_country(1123).nombre := 'Unidad Territorial de Vichada, con sede en Puerto Carreño';
	  t_country(1123).direccion := 'Carrera 6 No.20-93 Barrio Arturo Bueno';
