	  t_country(1127).idDepto := 6404;
	  t_country(1127).idMunicipio := 7314;
	  t_country(1127).nombre := 'Unidad Territorial de Vichada, con sede en Puerto Carreño';
	  t_country(1127).direccion := 'Carrera 6 No.20-93 Barrio Arturo Bueno';
	  t_country(1127).tipoPunto := 0;

	  -- Actualización de Puntos
	  << lookup >>
  
	  DBMS_OUTPUT.put_line ('Insercion y Actualización de Puntos de Notificación');
	  FOR i IN 1 .. 1127 LOOP
		IF t_country(i).tipoPunto = PUNTOATENCION THEN
    
		  --Decide cual es el adjetivo que debe ir ("del" o "de la")
		  IF upper(t_country(i).nombre) LIKE 'CENTRO%' THEN
			p_adjetivo := 'del ';
		  ELSE
			p_adjetivo := 'de la ';
		  END IF;
      
		  --Busca si existe este punto de notificación
		  SELECT COUNT(1) into conteo 
		  FROM TBPUNTOATENCION 
		  WHERE UPPER(REEMPLAZATILDES(t_country(i).nombre)) LIKE '%' || UPPER(REEMPLAZATILDES(nombre)) ||'%';
      
		  --Si el conteo es igual a 1, eso quiere decir que existe, así que actualiza
		  IF conteo = 1 THEN
			-- Se asigna el ID del punto de notificación para hacer la actualziación  
			SELECT ID into p_idPunto
			FROM TBPUNTOATENCION 
			WHERE UPPER(REEMPLAZATILDES(t_country(i).nombre)) LIKE '%' || UPPER(REEMPLAZATILDES(nombre)) ||'%';
        
			UPDATE TBPUNTOATENCION
			  SET NOMBRE = t_country(i).nombre,
				  TEXTONOMBRE = p_adjetivo || t_country(i).nombre,
				  DIRECCION = t_country(i).direccion,
				  TEXTODIRECCION = t_country(i).direccion
				  --IDMUNICIPIO = t_country(i).idMunicipio
			WHERE ID = p_idPunto;
		  ELSIF conteo = 0 THEN
			p_idPunto := SEQ_TBPUNTOATENCION.NEXTVAL;
			INSERT INTO TBPUNTOATENCION(ID, NOMBRE, TEXTONOMBRE, IDMUNICIPIO, DIRECCION, TEXTODIRECCION)
			VALUES(p_idPunto, t_country(i).nombre, p_adjetivo || t_country(i).nombre, t_country(i).idMunicipio, t_country(i).direccion, t_country(i).direccion);
		  END IF;
      
		  t_rules(i).IDDEPARTAMENTO := t_country(i).idDepto;
		  t_rules(i).IDMUNICIPIO := t_country(i).idMunicipio;
		  t_rules(i).IDPUNTOATENCION := p_idPunto;
		  t_rules(i).IDDIRECCIONTERRITORIAL := null;

		ELSIF t_country(i).tipoPunto = DIRECCIONTERRITORIAL THEN
      
		  SELECT COUNT(1) into conteo FROM TBDIRECCIONTERRITORIAL 
		  WHERE UPPER(REEMPLAZATILDES(t_country(i).nombre)) LIKE '%' || UPPER(REEMPLAZATILDES(nombre)) ||'%';
      
		  IF conteo = 1 THEN
      
			SELECT ID into p_idPunto
			FROM TBDIRECCIONTERRITORIAL 
			WHERE UPPER(REEMPLAZATILDES(t_country(i).nombre)) LIKE '%' || UPPER(REEMPLAZATILDES(nombre)) ||'%';
        
			UPDATE TBDIRECCIONTERRITORIAL
			  SET NOMBRE = t_country(i).nombre,
				  TEXTONOMBRE = 'de la ' || t_country(i).nombre,
				  DIRECCION = t_country(i).direccion,
				  TEXTODIRECCION = t_country(i).direccion
				  --IDMUNICIPIO = t_country(i).idMunicipio
			WHERE ID = p_idPunto;
		  ELSIF conteo = 0 THEN
			p_idPunto := SEQ_TBDIRECCIONTERRITORIAL.NEXTVAL;
			INSERT INTO TBDIRECCIONTERRITORIAL(ID, IDMUNICIPIO, NOMBRE, TEXTONOMBRE, DIRECCION, TEXTODIRECCION)
			VALUES(p_idPunto, t_country(i).idMunicipio, t_country(i).nombre, 'de la ' || t_country(i).nombre, t_country(i).direccion, t_country(i).direccion);
		  END IF;
      
		  t_rules(i).IDDEPARTAMENTO := t_country(i).idDepto;
		  t_rules(i).IDMUNICIPIO := t_country(i).idMunicipio;
		  t_rules(i).IDPUNTOATENCION := null;
		  t_rules(i).IDDIRECCIONTERRITORIAL := p_idPunto;
      
		END IF;
	  END LOOP;
	  commit;
  
	  DBMS_OUTPUT.put_line ('Inserción Relación Puntos de Notificación y Municipios');
	  FOR i IN 1 .. 1127 LOOP
  
		  SELECT count(1) INTO conteo
		  from TBREGLASNOTIFICACION 
		  where IDMUNICIPIO = t_rules(i).IDMUNICIPIO and IDDIRECCIONTERRITORIAL = t_rules(i).IDDIRECCIONTERRITORIAL and IDPUNTOATENCION = t_rules(i).IDPUNTOATENCION;
    
		  if conteo = 0 then
			INSERT INTO TBREGLASNOTIFICACION(ID,IDDEPARTAMENTO,IDMUNICIPIO,IDPUNTOATENCION,IDDIRECCIONTERRITORIAL)
			VALUES(SEQ_TBREGLASNOTIFICACION.NEXTVAL, t_rules(i).IDDEPARTAMENTO, t_rules(i).IDMUNICIPIO, t_rules(i).IDPUNTOATENCION, t_rules(i).IDDIRECCIONTERRITORIAL);
		  end if;
    
	  END LOOP; 
	  commit;
  
	END;
